function design(site, analyse) {
  const X = [0, 3.367, 6.733, 10.1, 13.467, 16.833, 20.2];
  const nodes = [];
  for (let i = 0; i < 7; i++) {
    nodes.push({id: 'LT' + i, x: X[i], y: 5, z: -2.7});
    nodes.push({id: 'RT' + i, x: X[i], y: 5, z: 2.7});
  }

  const G = {BC: [], TC: [], DG: [], VT: [], CX: [], XB: []};
  for (let i = 0; i < 6; i++) {
    G.BC.push(['L' + i, 'L' + (i + 1)], ['R' + i, 'R' + (i + 1)]);
    G.TC.push(['LT' + i, 'LT' + (i + 1)], ['RT' + i, 'RT' + (i + 1)]);
    if (i < 3) {
      G.DG.push(['LT' + i, 'L' + (i + 1)], ['RT' + i, 'R' + (i + 1)]);
    } else {
      G.DG.push(['L' + i, 'LT' + (i + 1)], ['R' + i, 'RT' + (i + 1)]);
    }
  }
  for (let i = 0; i < 7; i++) {
    G.VT.push(['L' + i, 'LT' + i], ['R' + i, 'RT' + i]);
    G.CX.push(['LT' + i, 'RT' + i], ['L' + i, 'R' + i]);
  }
  for (let i = 0; i < 6; i++) {
    G.XB.push(['LT' + i, 'RT' + (i + 1)], ['RT' + i, 'LT' + (i + 1)],
               ['L' + i, 'R' + (i + 1)], ['R' + i, 'L' + (i + 1)]);
  }

  const ord = ['BC', 'TC', 'DG', 'VT', 'CX', 'XB'];
  const S = {
    BC: ['S690 CHS60.3x4','S690 CHS76.1x3.2','S690 CHS76.1x4','S690 CHS88.9x4','S690 CHS88.9x5','S690 CHS114.3x4','S690 CHS114.3x5','S690 CHS139.7x5','S690 CHS139.7x6.3','S690 CHS168.3x5','S690 CHS168.3x6.3','S690 CHS193.7x6.3','S690 CHS193.7x8','S690 CHS219.1x8','S690 CHS244.5x8'],
    TC: ['S690 CHS60.3x4','S690 CHS76.1x3.2','S690 CHS76.1x4','S690 CHS88.9x4','S690 CHS88.9x5','S690 CHS114.3x4','S690 CHS114.3x5','S690 CHS139.7x5','S690 CHS139.7x6.3','S690 CHS168.3x5','S690 CHS168.3x6.3','S690 CHS193.7x6.3','S690 CHS193.7x8','S690 CHS219.1x8','S690 CHS244.5x8'],
    DG: ['S690 CHS48.3x3.2','S690 CHS60.3x3.2','S690 CHS60.3x4','S690 CHS76.1x3.2','S690 CHS76.1x4','S690 CHS88.9x4','S690 CHS88.9x5','S690 CHS114.3x4','S690 CHS114.3x5','S690 CHS139.7x5','S690 CHS139.7x6.3'],
    VT: ['S690 CHS48.3x3.2','S690 CHS60.3x3.2','S690 CHS60.3x4','S690 CHS76.1x3.2','S690 CHS76.1x4','S690 CHS88.9x4','S690 CHS88.9x5','S690 CHS114.3x4'],
    CX: ['S355 CHS42.4x3.2','S355 CHS48.3x3.2','S355 CHS60.3x3.2','S355 CHS60.3x4','S355 CHS76.1x3.2','S355 CHS76.1x4','S355 CHS88.9x4','S355 CHS88.9x5','S355 CHS114.3x4','S355 CHS114.3x5'],
    XB: ['WIRE WIRE8','WIRE WIRE10','WIRE WIRE12','WIRE WIRE16','WIRE WIRE20','WIRE WIRE24','WIRE WIRE32','WIRE WIRE40']
  };

  let ix = {BC: 7, TC: 7, DG: 5, VT: 3, CX: 3, XB: 3};

  function build() {
    const m = [];
    for (const g of ord) {
      for (const [a, b] of G[g]) {
        m.push([a, b, S[g][Math.min(ix[g], S[g].length - 1)]]);
      }
    }
    return {note: 'Two Pratt trusses at z=+-2.7 with cross and X bracing', nodes: nodes.map(n => ({...n})), members: m};
  }

  const idxMap = [];
  for (const g of ord) for (let i = 0; i < G[g].length; i++) idxMap.push(g);

  const visited = new Set();
  let best = null, bestM = 1e9;

  for (let it = 0; it < 250; it++) {
    const key = JSON.stringify(ix);
    if (visited.has(key)) break;
    visited.add(key);

    const d = build();
    const r = analyse(d);
    if (r.error) {
      for (const g of ord) ix[g] = Math.min(ix[g] + 1, S[g].length - 1);
      continue;
    }
    if (r.ok && r.mass < bestM) {
      bestM = r.mass;
      best = d;
    }

    const gU = {};
    for (const g of ord) gU[g] = 0;
    const nR = (r.members && r.members.length) || 0;
    for (let i = 0; i < Math.min(nR, idxMap.length); i++) {
      const g = idxMap[i];
      const u = r.members[i] && r.members[i].util;
      if (typeof u === 'number' && u > gU[g]) gU[g] = u;
    }
    for (const g of ord) if (gU[g] === 0) gU[g] = r.maxUtil || 1;

    let ch = false;
    for (const g of ord) {
      const u = gU[g];
      if (u > 0.95 && ix[g] < S[g].length - 1) {
        ix[g]++;
        ch = true;
      } else if (u < 0.55 && ix[g] > 0 && r.ok && (r.maxUtil || 1) < 0.9) {
        ix[g]--;
        ch = true;
      }
    }
    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.5) {
      if (ix.XB < S.XB.length - 1) { ix.XB++; ch = true; }
      if (ix.CX < S.CX.length - 1) { ix.CX++; ch = true; }
    }
    if (typeof r.frequency === 'number' && r.frequency < 4.2) {
      if (ix.TC < S.TC.length - 1) { ix.TC++; ch = true; }
      if (ix.BC < S.BC.length - 1) { ix.BC++; ch = true; }
    }
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > r.sagLimit * 0.7) {
      if (ix.TC < S.TC.length - 1) { ix.TC++; ch = true; }
      if (ix.BC < S.BC.length - 1) { ix.BC++; ch = true; }
    }
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > r.swayLimit * 0.7) {
      if (ix.CX < S.CX.length - 1) { ix.CX++; ch = true; }
      if (ix.XB < S.XB.length - 1) { ix.XB++; ch = true; }
    }

    if (!ch && r.ok) break;
  }

  return best || build();
}

