    }

    if (typeof r.alphaCr === 'number' && r.alphaCr < 3.5) {
      for (const g of ['TC','BC']) if (ix[g] < opts.length-1) { ix[g]++; ch = true; }
    }
    if (typeof r.frequency === 'number' && r.frequency < 4.2) {
      for (const g of ['TC','BC','VT']) if (ix[g] < opts.length-1) { ix[g]++; ch = true; }
