    const members = [];

    function top(side, i) { return (side === 0 ? "TL" : "TR") + i; }
    function bottom(side, i) { return (side === 0 ? "BL" : "BR") + i; }
    function deck(side, i) { return (side === 0 ? "L" : "R") + i; }
    function add(a, b, spec) { members.push([a, b, spec]); }

    for (let side = 0; side < 2; side++) {
      const z = side === 0 ? -2.7 : 2.7;

      for (let i = 0; i < 7; i++) {
        nodes.push({ id: top(side, i), x: xs[i], y: 5.85, z: z, joint: "pin" });
        nodes.push({ id: bottom(side, i), x: xs[i], y: -1.36, z: z, joint: "pin" });
        add(deck(side, i), bottom(side, i), c.post);
      }

      for (let i = 0; i < 6; i++) {
        add(top(side, i), top(side, i + 1), c.chord);
        add(bottom(side, i), bottom(side, i + 1), c.chord);

        // Crossed, compression-capable web diagonals.
        add(top(side, i), bottom(side, i + 1), c.side);
        add(bottom(side, i), top(side, i + 1), c.side);

        // Triangulated deck-to-lower-chord strip.
        add(deck(side, i), deck(side, i + 1), c.deckChord);
        add(deck(side, i), bottom(side, i + 1), c.lowerWeb);
      }
    }

    for (let i = 0; i < 7; i++) {
      add(top(0, i), top(1, i), c.tie);
      add(bottom(0, i), bottom(1, i), c.tie);
      add(deck(0, i), deck(1, i), c.deckBeam);
    }

    for (let i = 0; i < 6; i++) {
      // One compression-capable diagonal in each top and bottom plan bay.
      add(top(0, i), top(1, i + 1), c.plan);
      add(bottom(0, i), bottom(1, i + 1), c.plan);
    }

    return {
      note: "Two deep pinned side trusses, triangulated deck links, and braced top and bottom plans form a redundant steel box truss.",
      nodes: nodes,
      members: members
    };
  }

  function num(v, fallback) {
    return typeof v === "number" && isFinite(v) ? v : fallback;
  }

  function fatigueRatio(f) {
    if (typeof f === "number") return f > 2 ? f / 110 : f;
    if (f && typeof f === "object") {
      if (typeof f.util === "number") return f.util;
      if (typeof f.range === "number" && typeof f.limit === "number" && f.limit > 0) {
        return f.range / f.limit;
      }
    }
    return 0;
  }

  function reportRisk(r) {
    let mu = num(r.maxUtil, NaN);
    if (!isFinite(mu) && Array.isArray(r.members)) {
      mu = 0;
      for (let i = 0; i < r.members.length; i++) {
        mu = Math.max(mu, num(r.members[i].util, 0));
      }
    }
    if (!isFinite(mu)) mu = r.ok ? 0 : 10;

    const sagLimit = num(r.sagLimit, 0);
    const swayLimit = num(r.swayLimit, 0);
    const sagRatio = sagLimit > 0 ? Math.abs(num(r.sag, sagLimit * 10)) / sagLimit : 0;
    const swayRatio = swayLimit > 0 ? Math.abs(num(r.sway, swayLimit * 10)) / swayLimit : 0;
    const cr = num(r.alpha_crMin, 0);
    const freq = num(r.frequency, 0);
    const fNeed = 1.2 * num(r.fMin, 3.8);

    return Math.max(
      mu / 0.66,
      sagRatio / 0.75,
      swayRatio / 0.75,
      cr > 0 ? 4.2 / cr : 10,
      freq > 0 ? fNeed / freq : 10,
      fatigueRatio(r.fatigueWorst) / 0.70
    );
  }

  let bestSafe = null;
  let bestOk = null;
  let bestAny = null;

  for (let i = 0; i < configs.length; i++) {
    const d = makeDesign(configs[i]);
    let r;

    try {
      r = analyse(d);
    } catch (e) {
      continue;
    }

    if (!r || r.error) continue;

    const risk = reportRisk(r);
    const mass = num(r.mass, 1e30);

    if (r.ok && risk <= 1 && (!bestSafe || mass < bestSafe.mass)) {
      bestSafe = { design: d, mass: mass };
    }

    if (r.ok) {
      const quality = risk + mass * 1e-7;
      if (!bestOk || quality < bestOk.quality) {
        bestOk = { design: d, quality: quality };
      }
    }

    const qualityAny = risk + (r.ok ? 0 : 100) + mass * 1e-7;
    if (!bestAny || qualityAny < bestAny.quality) {
      bestAny = { design: d, quality: qualityAny };
    }
  }

  if (bestSafe) return bestSafe.design;
  if (bestOk) return bestOk.design;
  if (bestAny) return bestAny.design;
  return makeDesign(configs[configs.length - 1]);
}

