    const frequency = num(r.frequency, 0);
    const fatigue = fatigueRatio(r.fatigueWorst);

    const rb = r.robustness;
    const robustnessBad =
      rb === false ||
      (rb && typeof rb === "object" &&
       (rb.ok === false || rb.pass === false));

    let risk = Math.max(
      u / 0.64,
      cr > 0 ? 4.8 / cr : 10,
      frequency > 0 ? 4.6 / frequency : 10,
      fatigue / 0.8,
      sag,
