    if (!b) return true;
    if (a.safe !== b.safe) return a.safe;
    if (a.ok !== b.ok) return a.ok;

    if (a.safe) {
      if (a.mass !== b.mass) return a.mass < b.mass;
      return a.risk < b.risk;
    }

    if (Math.abs(a.risk - b.risk) > 0.002) return a.risk < b.risk;
    if (a.mass !== b.mass) return a.mass < b.mass;
    return a.risk < b.risk;
