  const cache = Object.create(null);
  const maxCalls = 380;
  let calls = 0;
  let bestSafe = null;
  let bestAny = null;

  function evaluate(fam, c) {
    const key = fam.id + "|" + fam.z + "|" +
                fam.fields.map(f => c[f]).join("|");
    if (Object.prototype.hasOwnProperty.call(cache, key)) return cache[key];
    if (calls >= maxCalls) return null;

    calls++;
    const d = make(fam, c);
    let r;
    try {
