      return null;
    }

    const a = assess(r);
    const rec = {
      fam: fam,
      c: Object.assign({}, c),
      design: d,
      mass: num(r.mass, 1e30),
      risk: a.risk,
      safe: a.safe,
      ok: !!r.ok
    };

    if (rec.safe && better(rec, bestSafe)) bestSafe = rec;
    if (better(rec, bestAny)) bestAny = rec;
