    if (!current) return null;

    for (const field of fam.fields) {
      if (calls >= maxCalls) break;

      const start = Object.assign({}, current.c);
      let choice = current;
      const list = sectionOptions(field);

      for (const value of list) {
        if (calls >= maxCalls) break;
        if (value === start[field]) continue;

        const candidate = Object.assign({}, start);
        candidate[field] = value;
        const rec = evaluate(fam, candidate);
        if (rec && better(rec, choice)) choice = rec;
      }
      current = choice;
