    function add(a, b, s) {
      members.push([a, b, s]);
    }

    for (const side of ["L", "R"]) {
      const top = i => "T" + side + i;
      const bot = i => side + i;

      for (let i = 0; i < 6; i++) {
        const st = (i === 0 || i === 5) ? secs[p.topChordEnd] : secs[p.topChordMid];
        add(top(i), top(i + 1), st);

        const sb = (i === 0 || i === 5) ? secs[p.bottomChordEnd] : secs[p.bottomChordMid];
        add(bot(i), bot(i + 1), sb);
      }

      for (let i = 0; i <= 6; i++) {
        const sv = (i === 0 || i === 6) ? secs[p.verticalEnd] : secs[p.verticalMid];
        add(bot(i), top(i), sv);
      }

      for (let i = 0; i < 6; i++) {
        let sd;
        if (i === 0 || i === 5) sd = secs[p.diagEnd];
        else if (i === 1 || i === 4) sd = secs[p.diagNear];
        else sd = secs[p.diagMid];

        let a, b;
        if (i < 3) {
          a = bot(i);
          b = top(i + 1);
        } else {
          a = bot(i + 1);
          b = top(i);
        }
        add(a, b, sd);
      }
    }

    for (let i = 0; i <= 6; i++) {
      add("TL" + i, "TR" + i, secs[p.topCross]);
      add("L" + i, "R" + i, secs[p.bottomCross]);
    }

    for (let i = 0; i < 6; i++) {
      if (i % 2 === 0) add("TL" + i, "TR" + (i + 1), secs[p.topBrace]);
      else add("TR" + i, "TL" + (i + 1), secs[p.topBrace]);

      if (i % 2 === 0) add("L" + i, "R" + (i + 1), secs[p.bottomBrace]);
      else add("R" + i, "L" + (i + 1), secs[p.bottomBrace]);
    }

    add("TL0", "R0", secs[p.endBrace]);
    add("TR0", "L0", secs[p.endBrace]);
    add("TL6", "R6", secs[p.endBrace]);
    add("TR6", "L6", secs[p.endBrace]);

