    let utilLim, alphaMin, freqMin, sagFrac, swayFrac, fatLim;
    if (level === 0) {
      utilLim = 0.55;
      alphaMin = 8.0;
      freqMin = 4.5;
      sagFrac = 0.60;
      swayFrac = 0.60;
      fatLim = 0.80;
    } else if (level === 1) {
      utilLim = 0.72;
      alphaMin = 6.0;
      freqMin = 4.2;
      sagFrac = 0.80;
      swayFrac = 0.80;
      fatLim = 0.92;
    } else {
      utilLim = 0.95;
      alphaMin = 3.2;
      freqMin = 3.85;
      sagFrac = 0.95;
      swayFrac = 0.95;
      fatLim = 1.05;
    }

    if (typeof r.maxUtil === "number" && r.maxUtil > utilLim) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < alphaMin) return false;
    if (typeof r.frequency === "number" && r.frequency < freqMin) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > sagFrac * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > swayFrac * r.swayLimit) return false;

    if (typeof r.fatigueWorst === "number" && r.fatigueWorst <= 5 && r.fatigueWorst > fatLim) return false;
    if (r.robustness === false) return false;

