    H: 4.85,
    topChordEnd: 14,
    topChordMid: 16,
    bottomChordEnd: 13,
    bottomChordMid: 15,
    diagEnd: 16,
    diagNear: 14,
    diagMid: 12,
    verticalEnd: 9,
    verticalMid: 11,
    topCross: 8,
    bottomCross: 9,
    topBrace: 7,
    bottomBrace: 7,
    endBrace: 11
  };

  const heavy = { H: 4.85 };
  for (const d of paramDefs) heavy[d.name] = d.max;

  const rInitial = evalP(initial);
  const rHeavy = evalP(heavy);

  let levelUsed = 0;
  let base = null;

  if (passes(rInitial, 0)) base = { p: Object.assign({}, initial), r: rInitial };
  else if (passes(rHeavy, 0)) base = { p: Object.assign({}, heavy), r: rHeavy };

  if (!base) {
    levelUsed = 1;
    if (passes(rInitial, 1)) base = { p: Object.assign({}, initial), r: rInitial };
    else if (passes(rHeavy, 1)) base = { p: Object.assign({}, heavy), r: rHeavy };
  }

  if (!base) {
    levelUsed = 2;
    if (passes(rInitial, 2)) base = { p: Object.assign({}, initial), r: rInitial };
    else if (passes(rHeavy, 2)) base = { p: Object.assign({}, heavy), r: rHeavy };
    else base = { p: Object.assign({}, heavy), r: rHeavy };
  }

