    let cur = Object.assign({}, startP);
    let curR = evalP(cur);
    if (!passes(curR, level)) {
      return { p: Object.assign({}, cur), r: curR };
    }

    let bestP = Object.assign({}, cur);
    let bestR = curR;
    let changed = true;
    let passNo = 0;

    while (changed && passNo < maxPasses && calls < 390) {
      changed = false;
      passNo++;

      const order = (passNo % 2 === 1)
        ? paramDefs.slice()
        : paramDefs.slice().reverse();

      for (const d of order) {
        if (calls >= 390) break;
        const curIdx = cur[d.name];
        if (curIdx <= d.min) continue;

        for (let t = d.min; t < curIdx; t++) {
          if (calls >= 390) break;
          const q = Object.assign({}, cur);
          q[d.name] = t;
