  const first = runDescent(base.p, levelUsed, 4);
  if (first.r && passes(first.r, levelUsed) && massOf(first.r) < massOf(bestOverall.r)) {
    bestOverall = first;
  }

  if (calls < 260) {
    const alt = Object.assign({}, bestOverall.p);
    for (const d of paramDefs) {
      alt[d.name] = Math.min(d.max, (alt[d.name] || d.min) + 1);
    }
    const rAlt = evalP(alt);
    if (passes(rAlt, levelUsed)) {
      const second = runDescent(alt, levelUsed, 2);
      if (second.r && passes(second.r, levelUsed) && massOf(second.r) < massOf(bestOverall.r)) {
        bestOverall = second;
      }
    }
  }

  if (calls < 330) {
    const mid = { H: 4.85 };
