      mid[d.name] = Math.floor((d.min + d.max) / 2);
    }
    const rMid = evalP(mid);
    if (passes(rMid, levelUsed)) {
      const third = runDescent(mid, levelUsed, 2);
      if (third.r && passes(third.r, levelUsed) && massOf(third.r) < massOf(bestOverall.r)) {
        bestOverall = third;
      }
    }
  }

  let finalP = bestOverall && bestOverall.p ? bestOverall.p : heavy;
  const out = build(finalP);
  out.note = "Light S690 closed box truss: parallel chords, single side diagonals, full top/bottom plan bracing, end X-diaphragms, sized for worst-unit margins.";
  return out;
}

