  const CHS = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53],
    ["CHS60.3x3.2", 5.74], ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67], ["CHS88.9x5", 13.18],
    ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x6.3", 37.09], ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06],
    ["CHS244.5x8", 59.44], ["CHS273x10", 82.62], ["CHS323.9x10", 98.61],
