    ["SHS70x4", 10.56], ["SHS80x5", 15], ["SHS90x5", 17],
    ["SHS100x5", 19], ["SHS100x8", 29.44], ["SHS120x6", 27.36],
    ["SHS140x6", 32.16], ["SHS150x8", 45.44], ["SHS180x8", 55.04],
    ["SHS200x10", 76], ["SHS250x10", 96], ["SHS300x12.5", 143.75],
    ["SHS350x16", 213.76]
  ];

  const WIRES = [
    ["WIRE8", 0.3], ["WIRE10", 0.47], ["WIRE12", 0.68], ["WIRE16", 1.21],
    ["WIRE20", 1.88], ["WIRE24", 2.71], ["WIRE32", 4.83], ["WIRE40", 7.54]
  ];

  const CAT = [];
  for (const [id, A] of CHS) {
    CAT.push({ spec: "S690 " + id, mass: 0.785 * A });
    CAT.push({ spec: "AL7075 " + id, mass: 0.281 * A });
  }
  for (const [id, A] of SHS) {
    CAT.push({ spec: "AL7075 " + id, mass: 0.281 * A });
  }
  for (const [id, A] of WIRES) {
