      }
    }

    for (let i = 0; i <= 6; i++) {
      const cg = (i === 0 || i === 6) ? 13 :
                 (i === 1 || i === 5) ? 14 :
                 (i === 2 || i === 4) ? 15 : 16;
      add("TL" + i, "TR" + i, cg);
    }

    for (let i = 0; i <= 6; i++) {
      const cg = (i === 0 || i === 6) ? 17 :
                 (i === 1 || i === 5) ? 18 :
                 (i === 2 || i === 4) ? 19 : 20;
