      add("A"+s+"1","A"+s+"2",1);
      add("A"+s+"2","A"+s+"3",2);
      add("A"+s+"3","A"+s+"4",2);
      add("A"+s+"4","A"+s+"5",1);
      add("A"+s+"5",s+"6",0);

      add("A"+s+"1",s+"1",3);
      add("A"+s+"2",s+"2",4);
      add("A"+s+"3",s+"3",5);
      add("A"+s+"4",s+"4",4);
      add("A"+s+"5",s+"5",3);

      add(s+"1","A"+s+"2",6);
      add(s+"2","A"+s+"3",7);
      add(s+"4","A"+s+"3",7);
      add(s+"5","A"+s+"4",6);

      if (both) {
        add(s+"2","A"+s+"1",6);
        add(s+"3","A"+s+"2",7);
        add(s+"3","A"+s+"4",7);
        add(s+"4","A"+s+"5",6);
      }

      for (let i=0;i<6;i++) {
        if (bottomMode === "all" || (bottomMode === "ends" && (i===0 || i===5))) {
          add(s+i, s+(i+1), 8);
        }
      }
    }

    for (let i=0;i<=6;i++) {
      add("L"+i,"R"+i, (i===0 || i===6) ? 9 : 10);
    }

    for (let i=0;i<6;i++) {
      if (i % 2 === 0) add("L"+i,"R"+(i+1),11);
      else add("R"+i,"L"+(i+1),11);
    }

    const high = [];
    for (let i=1;i<=5;i++) if (ys[i-1] >= 4.8 - 1e-6) high.push(i);

    for (const i of high) add("AL"+i,"AR"+i,12);
    for (let k=0;k+1<high.length;k++) {
      const a = high[k], b = high[k+1];
