    if (!r || r.error || r.ok === false || r.failure) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > L.util) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < L.alpha) return false;
    if (typeof r.frequency === "number" && r.frequency < L.freq) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" &&
        r.sag > L.sag * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" &&
        r.sway > L.sway * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > L.fatigue) return false;
    if (r.robustness === false) return false;
    return true;
  }

