    let bestP = p.slice();
    let bestR = r;
    let bestMass = r.mass;
    const active = activeGroups(opt);
    const baseOrder = [0,1,2,6,7,3,4,5,8,9,10,11,12,13];
    const order = baseOrder.filter(g => active.indexOf(g) >= 0);

    for (let passNo=0; passNo<maxPasses; passNo++) {
      if (calls >= maxCalls) break;
      let changed = false;
      const ord = (passNo % 2) ? order.slice().reverse() : order.slice();

      for (const g of ord) {
        if (calls >= maxCalls) break;
        const cur = p[g];
        if (cur <= 0) continue;

        let lo = -1;
        let hi = cur;
        let rHi = null;

        while (hi - lo > 1 && calls < maxCalls) {
          const mid = Math.floor((lo + hi) / 2);
          const q = p.slice();
          q[g] = mid;
          const rr = runOpt(opt,q);
          if (pass(rr,L)) {
            hi = mid;
            rHi = rr;
          } else {
            lo = mid;
          }
        }

        if (hi < cur && rHi && pass(rHi,L)) {
          p[g] = hi;
          r = rHi;
          changed = true;
          if (r.mass < bestMass - 1e-7) {
            bestMass = r.mass;
            bestP = p.slice();
            bestR = r;
          }
        }
      }
      if (!changed) break;
    }

    if (pass(r,L) && r.mass < bestMass - 1e-7) {
      bestP = p.slice();
      bestR = r;
    }
    return {p:bestP, r:bestR};
  }

