    {W:4.2, ys:[4.80,5.50,5.85,5.50,4.80], bottomMode:"ends", bothDiag:false},
    {W:4.2, ys:[3.25,5.20,5.85,5.20,3.25], bottomMode:"all",  bothDiag:false},
    {W:4.5, ys:[4.80,5.50,5.85,5.50,4.80], bottomMode:"ends", bothDiag:false},
    {W:4.2, ys:[4.80,5.50,5.85,5.50,4.80], bottomMode:"ends", bothDiag:true},
    {W:3.8, ys:[4.80,5.50,5.85,5.50,4.80], bottomMode:"all",  bothDiag:false}
  ];

