  let bestR = null;

  for (let ci=0; ci<configs.length; ci++) {
    if (calls >= 392) break;
    const opt = configs[ci];

    let start = null;
    let rStart = null;

    for (const base of [p0,pHeavy]) {
      if (calls >= 392) break;
      const rr = runOpt(opt,base);
      if (pass(rr,LEVEL)) {
        start = base.slice();
        rStart = rr;
        break;
      }
    }
    if (!start) continue;

    const budget = Math.min(395, calls + (ci === 0 ? 120 : 90));
    const res = optimize(opt,start,LEVEL,budget,2);

    if (res && res.r && pass(res.r,LEVEL)) {
      if (res.r.mass < bestMass - 1e-6) {
        bestMass = res.r.mass;
        bestP = res.p.slice();
        bestOpt = JSON.parse(JSON.stringify(opt));
        bestR = res.r;
      }
    } else if (rStart && pass(rStart,LEVEL)) {
      if (rStart.mass < bestMass - 1e-6) {
        bestMass = rStart.mass;
        bestP = start.slice();
        bestOpt = JSON.parse(JSON.stringify(opt));
        bestR = rStart;
      }
    }
  }

  if (bestP && bestOpt && bestMass < 4000) {
