      add(A(1),A(2),1);
      add(A(2),A(3),2);
      add(A(3),A(4),2);
      add(A(4),A(5),1);
      add(A(5),s+"6",0);

      add(A(1),s+"1",3);
      add(A(5),s+"5",3);
      add(A(2),s+"2",4);
      add(A(4),s+"4",4);
      add(A(3),s+"3",5);

      add(s+"1",A(2),6);
      add(s+"5",A(4),6);
      add(s+"2",A(3),7);
      add(s+"4",A(3),7);

      add(s+"0",s+"1",8);
      add(s+"5",s+"6",8);
      add(s+"1",s+"2",9);
      add(s+"4",s+"5",9);
      add(s+"2",s+"3",10);
      add(s+"3",s+"4",10);
    }

    add("L0","R0",11);
    add("L6","R6",11);
    add("L1","R1",12);
    add("L5","R5",12);
    add("L2","R2",13);
    add("L3","R3",13);
