    for (let i=0;i<6;i++) {
      if (i % 2 === 0) add("L"+i,"R"+(i+1),14);
      else add("R"+i,"L"+(i+1),14);
    }

    const high = [];
    for (let i=1;i<=5;i++) if (ys[i-1] >= 4.8 - 1e-6) high.push(i);
