    if (calls >= limit) return null;
    let p = start.slice();
    let r = run(geo,p);
    if (!pass(r,L)) return null;

    let bestP = p.slice();
    let bestR = r;
    let bestMass = r.mass;
    const order = [0,1,2,8,9,10,6,7,14,11,12,13,3,4,5,15,16];

    for (let passNo=0; passNo<3; passNo++) {
      if (calls >= limit) break;
      let changed = false;
      const ord = (passNo % 2 === 1) ? order.slice().reverse() : order;

      for (const g of ord) {
        if (calls >= limit) break;
        const cur = p[g];
        if (cur <= 0) continue;

        let lo = -1;
        let hi = cur;
        let rHi = null;

        while (hi - lo > 1 && calls < limit) {
          const mid = Math.floor((lo + hi) / 2);
          const q = p.slice();
          q[g] = mid;
          const rr = run(geo,q);
          if (pass(rr,L)) {
            hi = mid;
            rHi = rr;
          } else {
            lo = mid;
          }
        }

        if (hi < cur && rHi && pass(rHi,L)) {
          p[g] = hi;
          r = rHi;
          changed = true;
          if (r.mass < bestMass - 1e-7) {
            bestMass = r.mass;
            bestP = p.slice();
            bestR = r;
          }
        }
      }
      if (!changed) break;
    }

    if (pass(r,L) && r.mass < bestMass - 1e-7) {
      bestP = p.slice();
      bestR = r;
    }
    return {p:bestP, r:bestR};
  }

  let bestSafeMass = fbMass;
  let bestSafeP = null;
  let bestSafeGeo = null;
  let bestSafeR = null;

  let bestRelaxMass = fbMass;
  let bestRelaxP = null;
  let bestRelaxGeo = null;
  let bestRelaxR = null;

  function consider(geo,p,r) {
    if (!r || r.error || typeof r.mass !== "number") return;
    if (pass(r,L_SAFE) && r.mass < bestSafeMass - 1e-7) {
      bestSafeMass = r.mass;
      bestSafeP = p.slice();
      bestSafeGeo = JSON.parse(JSON.stringify(geo));
      bestSafeR = r;
    }
    if (pass(r,L_OK) && r.mass < bestRelaxMass - 1e-7) {
      bestRelaxMass = r.mass;
      bestRelaxP = p.slice();
      bestRelaxGeo = JSON.parse(JSON.stringify(geo));
      bestRelaxR = r;
    }
  }

  const geos = [
    {W:4.45, ys:[3.24,5.19,5.84,5.19,3.24]},
