    H:"S690 CHS60.3x3.2",
    I:"S690 CHS48.3x3.2",
    J:"AL7075 CHS323.9x10",
    K:"AL7075 CHS193.7x8",
    L:"AL7075 CHS168.3x5",
    M:"AL7075 CHS88.9x5",
    N:"AL7075 CHS76.1x3.2",
    O:"AL7075 CHS60.3x4",
    P:"AL7075 CHS76.1x3.2",
    Q:"S690 CHS76.1x4",
    R:"AL7075 CHS88.9x5",
    S:"S690 CHS60.3x3.2",
    T:"AL7075 CHS139.7x5",
    U:"AL7075 CHS168.3x6.3",
    V:"AL7075 SHS120x6",
    W:"S690 CHS76.1x4",
    X:"S690 CHS114.3x4"
  };
  const startP = G_NAMES.map(g=>startSpecs[g]);

  const CAT_MAP = {};
  const UP_MAP = {};
  function makeCat(mat,fam,arr) {
    const list = arr.map(([id,A]) => ({spec:mat+" "+id, A:A}));
    list.sort((a,b)=>a.A-b.A);
    CAT_MAP[mat+"|"+fam] = list.map(o=>o.spec);
    UP_MAP[mat+"|"+fam] = arr.map(([id,A])=>mat+" "+id);
  }
  makeCat("AL7075","CHS",CHS);
  makeCat("S690","CHS",CHS);
  makeCat("AL7075","SHS",SHS);
  makeCat("S690","SHS",SHS);

  function parseSpec(spec) {
    const parts = spec.split(" ");
    const mat = parts[0];
    const rest = parts.slice(1).join(" ");
    const m = rest.match(/^[A-Za-z]+/);
    const fam = m ? m[0] : "";
    return {mat:mat, fam:fam, rest:rest};
  }
  function getCands(spec) {
    const ps = parseSpec(spec);
    return CAT_MAP[ps.mat+"|"+ps.fam] || [spec];
  }

  const cands = {};
  for (const g of G_NAMES) cands[g] = getCands(startSpecs[g]);

  const TOPO = [];
  const addTopo = (a,b,g)=>TOPO.push([a,b,g]);

  // top longitudinal chords
  for (let i=0;i<6;i++) {
    let g;
    if (i===0 || i===5) g = "A";
    else if (i===1 || i===4) g = "B";
    else g = "C";
    addTopo("TL"+i,"TL"+(i+1),g);
    addTopo("TR"+i,"TR"+(i+1),g);
  }
  // deck edge chords
  for (let i=0;i<6;i++) {
    let g;
    if (i===0 || i===5) g = "D";
    else if (i===1 || i===4) g = "E";
    else g = "F";
    addTopo("L"+i,"L"+(i+1),g);
    addTopo("R"+i,"R"+(i+1),g);
  }
  // side verticals
  for (let i=0;i<=6;i++) {
    let g;
    if (i===3) g = "I";
    else if (i===2 || i===4) g = "H";
    else g = "G";
    addTopo("L"+i,"TL"+i,g);
    addTopo("R"+i,"TR"+i,g);
  }
  // side diagonals
  addTopo("L0","TL1","J"); addTopo("L6","TL5","J");
  addTopo("R0","TR1","J"); addTopo("R6","TR5","J");
  addTopo("L1","TL2","K"); addTopo("L5","TL4","K");
  addTopo("R1","TR2","K"); addTopo("R5","TR4","K");
  addTopo("L2","TL3","L"); addTopo("L4","TL3","L");
  addTopo("R2","TR3","L"); addTopo("R4","TR3","L");
  // top transverse
  for (let i=0;i<=6;i++) {
    let g;
    if (i===0 || i===6) g = "M";
    else if (i===3) g = "P";
    else if (i===1 || i===5) g = "N";
    else g = "O";
    addTopo("TL"+i,"TR"+i,g);
  }
  // bottom transverse
  for (let i=0;i<=6;i++) {
    let g;
    if (i===0 || i===6) g = "Q";
    else if (i===1 || i===5) g = "R";
    else g = "S";
    addTopo("L"+i,"R"+i,g);
  }
  // top plan diagonals
  const topDiag = [
    ["TL0","TR1"],["TR1","TL2"],["TL2","TR3"],
    ["TR3","TL4"],["TL4","TR5"],["TR5","TL6"]
  ];
  for (const [a,b] of topDiag) addTopo(a,b,"T");
  // bottom plan diagonals
  addTopo("L0","R1","U"); addTopo("R5","L6","U");
  addTopo("R1","L2","V"); addTopo("L4","R5","V");
  addTopo("L2","R3","W"); addTopo("R3","L4","W");
  // end diaphragms
  addTopo("TL0","R0","X"); addTopo("TR0","L0","X");
  addTopo("TL6","R6","X"); addTopo("TR6","L6","X");

  const idToGroup = {};
  for (const [a,b,g] of TOPO) {
    idToGroup[a+"-"+b] = g;
    idToGroup[b+"-"+a] = g;
    idToGroup[a+b] = g;
    idToGroup[b+a] = g;
  }

  function build(Y,p) {
    const nodes = [];
    for (let i=0;i<=6;i++) {
      nodes.push({id:"TL"+i,x:X[i],y:Y[i],z:-2.7,joint:"pin"});
      nodes.push({id:"TR"+i,x:X[i],y:Y[i],z:2.7,joint:"pin"});
    }
    const members = TOPO.map(([a,b,g]) => [a,b,p[idx[g]]]);
    return {
      note:"Optimized AL7075/S690 through-truss with variable top camber.",
      nodes:nodes,
      joints:{},
      members:members
    };
  }

  let calls = 0;
  const cache = new Map();

  function run(Y,p) {
    const key = Y.map(v=>v.toFixed(3)).join(",")+"|"+p.join("|");
    if (cache.has(key)) return cache.get(key);
    if (calls >= 398) return {error:"analysis call limit"};
    calls++;
    let r;
    try {
      r = analyse(build(Y,p));
    } catch (e) {
      r = {error:String(e)};
    }
    cache.set(key,r);
    return r;
  }

  let fbR;
  try { fbR = analyse(fallback); }
  catch (e) { fbR = {error:String(e)}; }
  calls = 1;
  const fbMass = (fbR && typeof fbR.mass === "number") ? fbR.mass : 4072;

  const b = (fbR && !fbR.error && fbR.ok !== false) ? fbR : null;
  const LIM_UTIL = (b && typeof b.maxUtil === "number") ? Math.min(0.760, b.maxUtil + 0.002) : 0.755;
  const LIM_FREQ = (b && typeof b.frequency === "number") ? Math.max(3.980, b.frequency - 0.002) : 3.995;
  const LIM_ALPHA = (b && typeof b.alphaCr === "number") ? Math.min(4.0, b.alphaCr * 0.5) : 4.0;
  const LIM_FAT = (b && typeof b.fatigueWorst === "number") ? Math.min(0.80, b.fatigueWorst + 0.08) : 0.75;
  const LIM_SAG = 0.98;
  const LIM_SWAY = 0.98;

  function passSafe(r) {
    if (!r || r.error || r.ok === false || r.failure) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > LIM_UTIL) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < LIM_ALPHA) return false;
    if (typeof r.frequency === "number" && r.frequency < LIM_FREQ) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > LIM_SAG * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > LIM_SWAY * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > LIM_FAT) return false;
    if (r.robustness === false) return false;
    return true;
  }

  const order = ["J","K","D","G","C","E","F","B","A","T","U","V","L","M","N","O","P","Q","R","S","W","X","H","I"];

  function optimize(Y,pStart,maxCalls,passes) {
    let p = pStart.slice();
    let r = run(Y,p);
    if (!passSafe(r)) return null;

    let bestP = p.slice();
    let bestR = r;

    for (let passNo=0; passNo<passes; passNo++) {
      if (calls >= maxCalls) break;
      let changed = false;

      for (const g of order) {
        if (calls >= maxCalls) break;
        const list = cands[g];
        const curSpec = p[idx[g]];
        const curIdx = list.indexOf(curSpec);
        if (curIdx <= 0) continue;

        let lo = -1;
        let hi = curIdx;
        let hiR = r;

        while (hi - lo > 1 && calls < maxCalls) {
          const mid = Math.floor((lo + hi) / 2);
          const q = p.slice();
          q[idx[g]] = list[mid];
          const rr = run(Y,q);
          if (passSafe(rr)) {
            hi = mid;
            hiR = rr;
          } else {
            lo = mid;
          }
        }

        if (hi < curIdx) {
          p[idx[g]] = list[hi];
          r = hiR;
          changed = true;
          if (r.mass < bestR.mass - 1e-7) {
            bestP = p.slice();
            bestR = r;
          }
        }
      }
      if (!changed) break;
    }

    return {Y:Y.slice(), p:bestP, r:bestR};
  }

  function increaseGroupOnce(p,g) {
    const spec = p[idx[g]];
    const ps = parseSpec(spec);
    const up = UP_MAP[ps.mat+"|"+ps.fam] || [spec];
    let ci = up.indexOf(spec);
    if (ci >= 0 && ci < up.length - 1) {
      p[idx[g]] = up[ci+1];
      return true;
    }
    return false;
  }

  function worstGroup(r) {
    if (!r || !r.members) return null;
    let best = null;
    for (const m of r.members) {
      if (!m || typeof m.util !== "number") continue;
      let id = m.id;
      if (!id && m.a && m.b) id = m.a+"-"+m.b;
      if (!id) continue;
      let g = idToGroup[id];
      if (!g) g = idToGroup[id.replace(/\s/g,"")];
      if (g && (!best || m.util > best.util)) best = {g:g, util:m.util, mode:m.mode};
    }
    return best;
  }

  function repairToPass(Y,p,maxCalls) {
    p = p.slice();
    let r = run(Y,p);
    let iter = 0;

    while (!passSafe(r) && calls < maxCalls && iter < 30) {
      let did = false;

      if (typeof r.maxUtil === "number" && r.maxUtil > LIM_UTIL) {
        const w = worstGroup(r);
        if (w) did = increaseGroupOnce(p,w.g);
        if (!did) {
          for (const g of order) {
            if (increaseGroupOnce(p,g)) { did = true; break; }
          }
        }
      } else if (typeof r.frequency === "number" && r.frequency < LIM_FREQ) {
        for (const g of ["C","B","E","F","J","K","A","D","L","G","H","I"]) {
          if (increaseGroupOnce(p,g)) { did = true; break; }
        }
      } else if (typeof r.alphaCr === "number" && r.alphaCr < LIM_ALPHA) {
        for (const g of ["T","U","V","W","M","N","O","P","Q","R","S","X"]) {
          if (increaseGroupOnce(p,g)) { did = true; break; }
        }
      } else if (typeof r.fatigueWorst === "number" && r.fatigueWorst > LIM_FAT) {
        for (const g of ["J","K","L","G","H","I","U","V","W"]) {
          if (increaseGroupOnce(p,g)) { did = true; break; }
        }
      } else {
        for (const g of ["C","E","F","A","D","B","L","J","K","G"]) {
          if (increaseGroupOnce(p,g)) { did = true; break; }
        }
      }

      if (!did) break;
      r = run(Y,p);
      iter++;
    }

    return {p:p, r:r};
  }

  let globalBest = null;
  function record(res) {
    if (!res || !passSafe(res.r)) return;
    if (!globalBest || res.r.mass < globalBest.r.mass) {
      globalBest = {Y:res.Y.slice(), p:res.p.slice(), r:res.r};
    }
  }

  // 1. base geometry
  const Y0 = [4.8,4.8,4.8,4.8,4.8,4.8,4.8];
  let res0 = optimize(Y0, startP, Math.min(395, calls + 115), 2);
  if (res0) record(res0);

  // 2. raised camber
  const Y1 = [4.8,5.30,5.84,5.84,5.84,5.30,4.8];
  let pY1 = (res0 ? res0.p : startP).slice();
  if (!passSafe(run(Y1,pY1))) pY1 = startP.slice();
  let res1 = optimize(Y1, pY1, Math.min(395, calls + 105), 2);
  if (res1) record(res1);

  // 3. more arched
  const Y2 = [4.8,5.84,5.84,5.84,5.84,5.84,4.8];
  let pY2 = (globalBest ? globalBest.p : startP).slice();
  if (!passSafe(run(Y2,pY2))) pY2 = (res0 ? res0.p : startP).slice();
  let res2 = optimize(Y2, pY2, Math.min(395, calls + 80), 1);
  if (res2) record(res2);

  // 4. intermediate camber
  if (calls < 345) {
    const Y3 = [4.8,5.60,5.84,5.84,5.84,5.60,4.8];
    let pY3 = (globalBest ? globalBest.p : startP).slice();
    if (!passSafe(run(Y3,pY3))) pY3 = (res1 ? res1.p : startP).slice();
    let res3 = optimize(Y3, pY3, Math.min(395, calls + 65), 1);
    if (res3) record(res3);
  }

  // 5. targeted seeds with much smaller end diagonals and stronger middle diagonals
  if (calls < 380) {
    const Yuse = (globalBest ? globalBest.Y : Y1);
    const seeds = [
      {J:"AL7075 CHS219.1x8", L:"AL7075 CHS168.3x6.3"},
      {J:"AL7075 CHS193.7x8", L:"AL7075 CHS193.7x6.3"},
      {J:"AL7075 CHS168.3x6.3", L:"AL7075 CHS193.7x6.3", K:"AL7075 CHS193.7x6.3"},
      {J:"AL7075 CHS219.1x8", L:"AL7075 CHS168.3x6.3", C:"AL7075 CHS193.7x6.3"},
      {J:"AL7075 CHS244.5x8", L:"AL7075 CHS168.3x6.3", K:"AL7075 CHS193.7x6.3"}
    ];

    for (const s of seeds) {
      if (calls >= 390) break;
      let q = startP.slice();
      for (const k in s) {
        if (idx[k] !== undefined) q[idx[k]] = s[k];
      }
      const rep = repairToPass(Yuse, q, Math.min(395, calls + 14));
      if (passSafe(rep.r)) {
        const res = optimize(Yuse, rep.p, Math.min(395, calls + 40), 1);
        if (res) record(res);
      }
    }
  }

  // 6. final polish of the current best
  if (globalBest && calls < 390) {
    const res = optimize(globalBest.Y, globalBest.p, 395, 1);
    if (res) record(res);
  }

  if (globalBest && passSafe(globalBest.r) && globalBest.r.mass < fbMass - 5) {
    const d = build(globalBest.Y, globalBest.p);
    d.note = "Locally optimized AL7075/S690 through-truss with raised/cambered top chord and reduced oversized end diagonals.";
    return d;
  }

  return fallback;
}

function design(site, analyse) {
  // Pratt through-truss on the two edge lines (z = -2.7 and +2.7), top chord at y = 5.8 (above the traffic box).
  // Top nodes sit at every deck station. Top struts plus diagonals in the top plane brace the trusses sideways.
  // Floor beams and small bottom-plane diagonals tie the deck plane. Every joint is pinned.
  // Each member group takes its lightest CHS section from S355/S460/S690, found by binary search.
  const xs = [0, 3.367, 6.733, 10.1, 13.467, 16.833, 20.2];
  const H = 5.8, zL = -2.7, zR = 2.7;
  const SECS = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS139.7x6.3", 26.4], ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61], ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const MATS = [["S355", 355], ["S460", 460], ["S690", 690]];
  const cands = [];
  for (const [m, fy] of MATS) for (const [s, a] of SECS) cands.push({ spec: m + " " + s, area: a, fy: fy });
  cands.sort((p, q) => (p.area - q.area) || (p.fy - q.fy));

  const groups = ["botOut", "botMid", "topOut", "topMid", "vEnd", "vMid",
                  "dOut", "dMid", "strut", "tlat", "floor", "blat"];

  const build = (sz) => {
    const nodes = [], members = [];
    for (let i = 0; i < 7; i++) {
      nodes.push({ id: "TL" + i, x: xs[i], y: H, z: zL, joint: "pin" });
      nodes.push({ id: "TR" + i, x: xs[i], y: H, z: zR, joint: "pin" });
    }
    const add = (a, b, g) => members.push({ a: a, b: b, spec: sz[g] });
    for (const s of ["L", "R"]) {
      const T = (s === "L") ? "TL" : "TR";
      for (let i = 0; i < 6; i++) {
        const outer = (i === 0 || i === 5);
        add(s + i, s + (i + 1), outer ? "botOut" : "botMid");
        add(T + i, T + (i + 1), outer ? "topOut" : "topMid");
      }
      for (let i = 0; i < 7; i++) add(s + i, T + i, (i === 0 || i === 6) ? "vEnd" : "vMid");
      for (let i = 0; i < 6; i++) {
        const outer = (i === 0 || i === 5);
        const g = outer ? "dOut" : "dMid";
        if (i < 3) add(T + i, s + (i + 1), g);      // Pratt: slopes down toward midspan
        else add(T + (i + 1), s + i, g);
      }
    }
    for (let i = 0; i < 7; i++) {
      add("TL" + i, "TR" + i, "strut");
      add("L" + i, "R" + i, "floor");
    }
    for (let i = 0; i < 6; i++) {
      add("TL" + i, "TR" + (i + 1), "tlat");
      add("L" + i, "R" + (i + 1), "blat");
    }
    return { note: "", nodes: nodes, joints: {}, members: members };
  };

  let calls = 0;
  const t0 = Date.now();
  const UMAX = 0.9;
  const test = (sz) => {
    calls++;
    const d = build(sz);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return { good: false, r: null };
    let good = !!r.ok;
    if (typeof r.score === "number" && r.score <= 0) good = false;
    if (typeof r.maxUtil === "number" && r.maxUtil > UMAX) good = false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.9 * r.sagLimit) good = false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.9 * r.swayLimit) good = false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 3.5) good = false;
    if (typeof r.fMin === "number" && r.fMin < 4.0) good = false;
    return { good: good, r: r };
  };

  const idx = {};
  for (const g of groups) idx[g] = cands.length - 1;
  const sizesOf = () => {
    const s = {};
    for (const g of groups) s[g] = cands[idx[g]].spec;
    return s;
  };

  const base = test(sizesOf());
  if (base.good) {
    for (let pass = 0; pass < 3; pass++) {
      let changed = false;
      for (const g of groups) {
        if (Date.now() - t0 > 70000 || calls > 330) break;
        let lo = 0, hi = idx[g];
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          const save = idx[g];
          idx[g] = mid;
          const t = test(sizesOf());
          idx[g] = save;
          if (t.good) hi = mid; else lo = mid + 1;
        }
        if (hi !== idx[g]) { changed = true; idx[g] = hi; }
      }
      if (!changed) break;
    }
  }
  const out = build(sizesOf());
  out.note = "Pratt through-truss on the edge lines (top chord at y=5.8, all pinned) with top struts and top-plane diagonals for lateral bracing, floor beams and bottom-plane diagonals; CHS sizes per member group found by binary search to the lightest passing set with 10% margin.";
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  // Attempt-1 Pratt through-truss on the edge lines (z = -2.7 and +2.7), top chord at y = 5.8.
  // Diagnosis: the top and deck lateral bracing ride sideways relative to each other. Each side truss
  // is planar, so out-of-plane racking of its top chord (w = c*y) strains no member. The traffic box
  // (x 0..20.2, y 0..4.8, z -2.7..2.7) forbids any diagonal that crosses the bridge between top and deck,
  // so that racking cannot be braced by diagonals. Fix: make every joint rigid, so the side trusses
  // and the lateral trusses act as moment frames and racking is resisted by bending.
  // Sizes per member group are found by binary search to the lightest passing set with a 10% margin.
  const xs = [0, 3.367, 6.733, 10.1, 13.467, 16.833, 20.2];
  const H = 5.8, zL = -2.7, zR = 2.7;
  const SECS = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS139.7x6.3", 26.4], ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61], ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const MATS = [["S355", 355], ["S460", 460], ["S690", 690]];
  const cands = [];
  for (const [m, fy] of MATS) for (const [s, a] of SECS) cands.push({ spec: m + " " + s, area: a, fy: fy });
  cands.sort((p, q) => (p.area - q.area) || (p.fy - q.fy));

  const groups = ["botOut", "botMid", "topOut", "topMid", "vEnd", "vMid",
                  "dOut", "dMid", "strut", "tlat", "floor", "blat"];

  const build = (sz) => {
    const nodes = [], members = [], joints = {};
    for (let i = 0; i < 7; i++) {
      nodes.push({ id: "TL" + i, x: xs[i], y: H, z: zL, joint: "rigid" });
      nodes.push({ id: "TR" + i, x: xs[i], y: H, z: zR, joint: "rigid" });
      joints["L" + i] = "rigid";
      joints["R" + i] = "rigid";
    }
    const add = (a, b, g) => members.push({ a: a, b: b, spec: sz[g] });
    for (const s of ["L", "R"]) {
      const T = (s === "L") ? "TL" : "TR";
      for (let i = 0; i < 6; i++) {
        const outer = (i === 0 || i === 5);
        add(s + i, s + (i + 1), outer ? "botOut" : "botMid");
        add(T + i, T + (i + 1), outer ? "topOut" : "topMid");
      }
      for (let i = 0; i < 7; i++) add(s + i, T + i, (i === 0 || i === 6) ? "vEnd" : "vMid");
      for (let i = 0; i < 6; i++) {
        const outer = (i === 0 || i === 5);
        const g = outer ? "dOut" : "dMid";
        if (i < 3) add(T + i, s + (i + 1), g);      // Pratt: slopes toward midspan
        else add(T + (i + 1), s + i, g);
      }
    }
    for (let i = 0; i < 7; i++) {
      add("TL" + i, "TR" + i, "strut");
      add("L" + i, "R" + i, "floor");
    }
    for (let i = 0; i < 6; i++) {
      add("TL" + i, "TR" + (i + 1), "tlat");
      add("L" + i, "R" + (i + 1), "blat");
    }
    return { note: "", nodes: nodes, joints: joints, members: members };
  };

  let calls = 0;
  const t0 = Date.now();
  const UMAX = 0.9;
  const test = (sz) => {
    calls++;
    const d = build(sz);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return { good: false, r: null };
    let good = !!r.ok;
    if (typeof r.score === "number" && r.score <= 0) good = false;
    if (typeof r.maxUtil === "number" && r.maxUtil > UMAX) good = false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.9 * r.sagLimit) good = false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.9 * r.swayLimit) good = false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 3.5) good = false;
    if (typeof r.fMin === "number" && r.fMin < 4.0) good = false;
    return { good: good, r: r };
  };

  const idx = {};
  for (const g of groups) idx[g] = cands.length - 1;
  const sizesOf = () => {
    const s = {};
    for (const g of groups) s[g] = cands[idx[g]].spec;
    return s;
  };

  const base = test(sizesOf());
  if (base.good) {
    for (let pass = 0; pass < 3; pass++) {
      let changed = false;
      for (const g of groups) {
        if (Date.now() - t0 > 70000 || calls > 330) break;
        let lo = 0, hi = idx[g];
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          const save = idx[g];
          idx[g] = mid;
          const t = test(sizesOf());
          idx[g] = save;
          if (t.good) hi = mid; else lo = mid + 1;
        }
        if (hi !== idx[g]) { changed = true; idx[g] = hi; }
      }
      if (!changed) break;
    }
  }
  const out = build(sizesOf());
  out.note = "Attempt-1 Pratt through-truss with every joint rigid so side and lateral trusses act as moment frames and resist the out-of-plane racking that caused the mechanism; CHS sizes per group found by binary search with 10% margin.";
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

