function design(site, analyse) {
  // Pratt through-truss, all joints rigid (racking needs moment action; bearings cannot resist it).
  // New change: a rigid mid-height node on every vertical halves its buckling length (member length is the
  // buckling length in the checks), so verticals are sized for ~2.9 m instead of 5.8 m.
  // Sizing: fully-stressed iteration per member toward utilisation TARGET, with guards that raise minimum
  // sizes when frequency or global buckling fails. The lightest iterate that passes all margins is returned.
  const t0 = Date.now();
  const TARGET = 0.6;     // sizing utilisation (published cases, nominal)
  const UFEAS = 0.7;      // feasibility: max utilisation, leaves margin for built-unit spread
  const xs = [0, 3.367, 6.733, 10.1, 13.467, 16.833, 20.2];
  const H = 5.8, HM = 2.9, zL = -2.7, zR = 2.7;

  // S690 circular hollow sections, sorted by area (cm^2)
  const CH = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61], ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const NC = CH.length;
  const smallest = (need) => {
    for (let k = 0; k < NC; k++) if (CH[k][1] >= need) return k;
    return NC - 1;
  };
  const idxOf = (area) => {
    for (let k = 0; k < NC; k++) if (Math.abs(CH[k][1] - area) < 1e-6) return k;
    return NC - 1;
  };

  // Nodes: top chord (TL/TR at y=5.8) and mid-height vertical nodes (ML/MR at y=2.9)
  const nodes = [];
  for (let i = 0; i < 7; i++) {
    nodes.push({ id: "TL" + i, x: xs[i], y: H, z: zL, joint: "rigid" });
    nodes.push({ id: "TR" + i, x: xs[i], y: H, z: zR, joint: "rigid" });
    nodes.push({ id: "ML" + i, x: xs[i], y: HM, z: zL, joint: "rigid" });
    nodes.push({ id: "MR" + i, x: xs[i], y: HM, z: zR, joint: "rigid" });
  }
  const joints = {};
  for (let i = 0; i < 7; i++) { joints["L" + i] = "rigid"; joints["R" + i] = "rigid"; }

  // Member topology with group labels
  const MEM = [];
  const add = (a, b, g) => MEM.push({ a: a, b: b, g: g });
  for (const s of ["L", "R"]) {
    const T = (s === "L") ? "TL" : "TR";
    const Mn = (s === "L") ? "ML" : "MR";
    for (let i = 0; i < 6; i++) {
      add(s + i, s + (i + 1), "bot");
      add(T + i, T + (i + 1), "top");
    }
    for (let i = 0; i < 7; i++) {
      const g = (i === 0 || i === 6) ? "vE" : "vM";
      add(s + i, Mn + i, g);
      add(Mn + i, T + i, g);
    }
    for (let i = 0; i < 6; i++) {
      const g = (i === 0 || i === 5) ? "dE" : "dM";
      if (i < 3) add(T + i, s + (i + 1), g);      // Pratt: slopes toward midspan
      else add(T + (i + 1), s + i, g);
    }
  }
  for (let i = 0; i < 7; i++) {
    add("TL" + i, "TR" + i, "strut");
    add("L" + i, "R" + i, "floor");
  }
  for (let i = 0; i < 6; i++) {
    add("TL" + i, "TR" + (i + 1), "tlat");
    add("L" + i, "R" + (i + 1), "blat");
  }

  const START = { bot: 32.06, top: 32.06, vE: 21.16, vM: 21.16, dE: 13.18, dM: 13.18,
                  strut: 10.67, floor: 10.67, tlat: 10.67, blat: 10.67 };

  const build = (ixa) => ({
    note: "Pratt through-truss, all joints rigid, verticals split at mid-height nodes to halve buckling length; " +
          "per-member S690 CHS fully-stressed to 0.6 utilisation with frequency and global-buckling guards; lightest passing iterate.",
    nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: joints,
    members: MEM.map((m, k) => ({ a: m.a, b: m.b, spec: "S690 " + CH[ixa[k]][0] }))
  });

  const feasible = (r) => {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.score === "number" && r.score <= 0) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > UFEAS) return false;
    if (typeof r.fMin === "number" && r.fMin < 4.2) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 5) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.5 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.5 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.7) return false;
    if (r.robustness === false) return false;
    return true;
  };

  const ix = MEM.map(m => idxOf(START[m.g]));
  const minIx = MEM.map(() => 0);
  let calls = 0, best = null, lastD = null;
  const LIMIT_MS = 60000, MAXCALLS = 140;

  for (let it = 0; it < 45; it++) {
    if (Date.now() - t0 > LIMIT_MS || calls >= MAXCALLS) break;
    const d = build(ix);
    calls++;
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    lastD = d;
    if (!r || r.error) break;
    if (feasible(r) && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

    const mp = {};
    for (const e of (r.members || [])) mp[e.id] = e;

    const gBad = (typeof r.fMin === "number" && r.fMin < 4.2) ||
                 (typeof r.alphaCr === "number" && r.alphaCr < 5) ||
                 (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.5 * r.swayLimit) ||
                 (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.5 * r.sagLimit);
    let changed = false;
    if (gBad) {
      for (let k = 0; k < MEM.length; k++) minIx[k] = Math.min(NC - 1, Math.max(minIx[k], ix[k] + 1));
      changed = true;
    }

    const nx = ix.slice();
    for (let k = 0; k < MEM.length; k++) {
      const m = MEM[k];
      const e = mp[m.a + "-" + m.b] || mp[m.b + "-" + m.a];
      let want = ix[k];
      if (e && typeof e.util === "number") {
        const A = CH[ix[k]][1];
        const need = A * Math.pow(Math.max(e.util, 0.02) / TARGET, 0.7);
        want = smallest(need);
        if (String(e.mode || "").indexOf("fatigue") >= 0) want = Math.max(want, Math.min(NC - 1, ix[k] + 1));
      }
      want = Math.max(want, minIx[k]);
      if (want !== ix[k]) changed = true;
      nx[k] = want;
    }
    if (!changed) break;
    for (let k = 0; k < MEM.length; k++) ix[k] = nx[k];
  }

  const out = best ? best.d : (lastD || build(ix));
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

