    nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: T.joints,
    members: T.M.map((m, k) => ({ a: m.a, b: m.b, spec: "S690 " + CH[ix[k]][0] }))
  });

  const feasible = (r) => {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.score === "number" && r.score <= 0) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > U_FEAS) return false;
    if (typeof r.fMin === "number" && r.fMin < F_MIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < A_MIN) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > LIM_MARGIN * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > LIM_MARGIN * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > LIM_MARGIN) return false;
    if (r.robustness === false) return false;
    return typeof r.mass === "number";
  };

  let calls = 0, best = null;

  const runVariant = (V) => {
    const T = topo(V);
    const nm = T.M.length;
    const ix = new Array(nm).fill(14);      // start at S690 CHS168.3x6.3, shrink by utilisation
    const minIx = new Array(nm).fill(0);
    for (let it = 0; it < 26; it++) {
      if (Date.now() - t0 > DEADLINE || calls >= CAP) return;
      const d = mk(T, ix);
      calls++;
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) return;
      if (r.failure && /mechanism/i.test(String(r.failure))) return;
      if (feasible(r) && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };

      const mp = {};
      for (const e of (r.members || [])) mp[e.id] = e;

      const fBad = typeof r.fMin === "number" && r.fMin < F_MIN;
      const sagBad = typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > LIM_MARGIN * r.sagLimit;
      const swayBad = typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > LIM_MARGIN * r.swayLimit;
      const aBad = typeof r.alphaCr === "number" && r.alphaCr < A_MIN;

      const nx = ix.slice();
      let changed = false;
      for (let k = 0; k < nm; k++) {
        const m = T.M[k];
        const e = mp[m.a + "-" + m.b] || mp[m.b + "-" + m.a];
        let want = ix[k];
        if (e && typeof e.util === "number") {
          const A = CH[ix[k]][1];
          want = smallest(A * Math.max(e.util, 0.01) / T_FS);
        }
        let bump = false;
        if ((fBad || sagBad || swayBad) && (m.g === "bot" || m.g === "top")) bump = true;
        if (swayBad && (m.g === "strut" || m.g === "tlat" || m.g === "blat" || m.g === "floor")) bump = true;
        if (aBad) bump = true;
        if (bump) want = Math.max(want, ix[k] + 1);
        want = Math.min(NC - 1, Math.max(want, minIx[k]));
        if (bump) minIx[k] = Math.max(minIx[k], want);
        nx[k] = want;
        if (want !== ix[k]) changed = true;
      }
      if (!changed) return;
      for (let k = 0; k < nm; k++) ix[k] = nx[k];
    }
  };

  runVariant({ split: true, allRigid: false });
  runVariant({ split: false, allRigid: false });
  runVariant({ split: true, allRigid: true });

  if (best) {
    const out = best.d;
    return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
  }
  // Fallback: all-rigid split frame with the known-passing S690 CHS457x16 everywhere.
  const T3 = topo({ split: true, allRigid: true });
  const out = mk(T3, T3.M.map(() => NC - 1));
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  // Pratt through-truss, depth 5.8 m, all joints rigid (racking needs moment action; pinned bracing cannot
  // stop the cross-section from racking inside the traffic envelope). Verticals split at mid-height to halve
  // buckling length; end-face diagonals optional. Sizes: S690 CHS (d/t <= 28.6 so class 1-2 survives a
  // thinner built wall). Each member group is sized by binary search over the section list for the smallest
  // size whose group utilisation stays <= T_GRP, subject to frequency, global buckling, sag/sway and fatigue
  // guards. Only analysed designs are returned, so the output is always a checked design.
  const t0 = Date.now();
  const DEADLINE = 72000, CAP = 380;
  const xs = [0, 3.367, 6.733, 10.1, 13.467, 16.833, 20.2];
  const H = 5.8, HM = 2.9, zL = -2.7, zR = 2.7;
  const T_GRP = 0.6, U_FEAS = 0.68, F_MIN = 4.4, A_MIN = 5.0, S_LIM = 0.6, FAT_MAX = 0.7;

  // S690 CHS, sorted by area (cm^2), d/t <= 28.6
  const CH = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06], ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06],
    ["CHS273x10", 82.62], ["CHS355.6x12.5", 134.74], ["CHS457x16", 221.67]
  ];
  const NC = CH.length;
  const GROUPS = ["bot", "top", "dE", "dM", "vE", "vM", "strut", "floor", "tlat", "blat", "end"];

  let calls = 0, best = null;
  const outBudget = () => (Date.now() - t0 > DEADLINE) || calls >= CAP;

  const topo = (V) => {
    const nodes = [], joints = {}, M = [];
    for (let i = 0; i < 7; i++) {
      nodes.push({ id: "TL" + i, x: xs[i], y: H, z: zL, joint: "rigid" });
      nodes.push({ id: "TR" + i, x: xs[i], y: H, z: zR, joint: "rigid" });
      if (V.split) {
        nodes.push({ id: "ML" + i, x: xs[i], y: HM, z: zL, joint: "rigid" });
        nodes.push({ id: "MR" + i, x: xs[i], y: HM, z: zR, joint: "rigid" });
      }
      joints["L" + i] = "rigid";
      joints["R" + i] = "rigid";
    }
    const add = (a, b, g) => M.push({ a: a, b: b, g: g });
    for (const s of ["L", "R"]) {
      const T = (s === "L") ? "TL" : "TR";
      const Mn = (s === "L") ? "ML" : "MR";
      for (let i = 0; i < 6; i++) {
        add(s + i, s + (i + 1), "bot");
        add(T + i, T + (i + 1), "top");
      }
      for (let i = 0; i < 7; i++) {
        const g = (i === 0 || i === 6) ? "vE" : "vM";
        if (V.split) { add(s + i, Mn + i, g); add(Mn + i, T + i, g); }
        else add(s + i, T + i, g);
      }
      for (let i = 0; i < 6; i++) {
        const g = (i === 0 || i === 5) ? "dE" : "dM";
        if (i < 3) add(T + i, s + (i + 1), g);      // Pratt: slopes toward midspan
        else add(T + (i + 1), s + i, g);
      }
    }
    for (let i = 0; i < 7; i++) {
      add("TL" + i, "TR" + i, "strut");
      add("L" + i, "R" + i, "floor");
    }
    for (let i = 0; i < 6; i++) {
      add("TL" + i, "TR" + (i + 1), "tlat");
      add("L" + i, "R" + (i + 1), "blat");
    }
    if (V.endDiag) { add("L0", "TR0", "end"); add("R6", "TL6", "end"); }
    return { nodes: nodes, joints: joints, M: M };
  };

  const mk = (T, G) => ({
    note: "All-rigid Pratt through-truss with mid-height verticals; S690 CHS sized per member group by binary search to " +
          "the smallest section with group utilisation <= 0.6 under frequency, global-buckling, sag/sway and fatigue guards.",
    nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: T.joints,
    members: T.M.map(m => ({ a: m.a, b: m.b, spec: "S690 " + CH[G[m.g]][0] }))
  });

  const feasible = (r) => {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.score === "number" && r.score <= 0) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > U_FEAS) return false;
    if (typeof r.fMin === "number" && r.fMin < F_MIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < A_MIN) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > S_LIM * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > S_LIM * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FAT_MAX) return false;
    if (r.robustness === false) return false;
    return typeof r.mass === "number";
  };

  const grpUtil = (T, r, g) => {
    const mp = {};
    for (const e of (r.members || [])) mp[e.id] = e;
    let mx = -1, found = false;
    for (const m of T.M) {
      if (m.g !== g) continue;
      const e = mp[m.a + "-" + m.b] || mp[m.b + "-" + m.a];
      if (e && typeof e.util === "number") {
        found = true;
        if (e.util > mx) mx = e.util;
      }
    }
    if (!found) return (typeof r.maxUtil === "number") ? r.maxUtil : 1;
    return mx;
  };

  const passes = (T, r, g) => {
    if (!r || r.error || !r.ok) return false;
    if (r.failure && /mechanism/i.test(String(r.failure))) return false;
    if (typeof r.fMin === "number" && r.fMin < F_MIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < A_MIN) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > S_LIM * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > S_LIM * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FAT_MAX) return false;
    return grpUtil(T, r, g) <= T_GRP;
  };

  const evalD = (T, G) => {
    if (outBudget()) return null;
    const d = mk(T, G);
    calls++;
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return { r: null, d: d };
    if (feasible(r) && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };
    return { r: r, d: d };
  };

  // Smallest passing index for group g; the current index is always a known pass (or the start).
  const searchGroup = (T, G, g) => {
    let lo = 0, hi = G[g];
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      const G2 = Object.assign({}, G);
      G2[g] = mid;
      const ev = evalD(T, G2);
      if (!ev) break;
      if (passes(T, ev.r, g)) hi = mid; else lo = mid + 1;
    }
    G[g] = hi;
  };

  const runTopo = (V, sweeps) => {
    const T = topo(V);
    const present = {};
    for (const m of T.M) present[m.g] = true;
    const groups = GROUPS.filter(g => present[g]);
    const G = {};
    for (const g of groups) G[g] = NC - 1;
    for (let s = 0; s < sweeps; s++) {
      for (const g of groups) {
        if (outBudget()) return;
        searchGroup(T, G, g);
      }
      if (outBudget()) return;
      evalD(T, G);
    }
  };

  runTopo({ split: true, endDiag: true }, 2);
  if (!outBudget()) runTopo({ split: false, endDiag: true }, 2);
  if (!outBudget()) runTopo({ split: true, endDiag: false }, 1);

  if (best) {
    return { note: best.d.note, nodes: best.d.nodes, joints: best.d.joints, members: best.d.members };
  }
  // Fallback: the all-CHS457x16 split, all-rigid frame that passed in attempt 5.
  const T3 = topo({ split: true, endDiag: true });
  const G3 = {};
  for (const m of T3.M) G3[m.g] = NC - 1;
  const fb = mk(T3, G3);
  return { note: fb.note, nodes: fb.nodes, joints: fb.joints, members: fb.members };
}

