        if (V.split) { add(s + i, Mn + i, g); add(Mn + i, T + i, g); }
        else add(s + i, T + i, g);
      }
      for (let i = 0; i < 6; i++) {
        const g = (i === 0 || i === 5) ? "dE" : "dM";
        if (i < 3) add(T + i, s + (i + 1), g);   // Pratt: slopes toward midspan
