    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x5", 17.17], ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS273x10", 82.62]
  ];
  const NC = CH.length;
  const GROUPS = ["bot", "top", "dE", "dM", "vE", "vM", "strut", "floor", "tlat", "blat", "end"];
  const START = { bot: 7, top: 10, dE: 8, dM: 7, vE: 7, vM: 7, strut: 3, floor: 3, tlat: 2, blat: 2, end: 8 };

  let calls = 0, best = null;
  const outBudget = () => (Date.now() - t0 > DEADLINE) || calls >= CAP;
  const smallest = (need) => {
    for (let k = 0; k < NC; k++) if (CH[k][1] >= need) return k;
    return NC - 1;
  };

  const topo = (V) => {
    const nodes = [], joints = {}, M = [];
    for (let i = 0; i < 7; i++) {
      nodes.push({ id: "TL" + i, x: xs[i], y: H, z: zL, joint: "rigid" });
      nodes.push({ id: "TR" + i, x: xs[i], y: H, z: zR, joint: "rigid" });
      if (V.split) {
        nodes.push({ id: "ML" + i, x: xs[i], y: HM, z: zL, joint: "rigid" });
        nodes.push({ id: "MR" + i, x: xs[i], y: HM, z: zR, joint: "rigid" });
      }
      joints["L" + i] = V.deck;
      joints["R" + i] = V.deck;
    }
    const add = (a, b, g) => M.push({ a: a, b: b, g: g });
    for (const s of ["L", "R"]) {
      const TT = (s === "L") ? "TL" : "TR";
      const Mn = (s === "L") ? "ML" : "MR";
      for (let i = 0; i < 6; i++) {
        add(s + i, s + (i + 1), "bot");
        add(TT + i, TT + (i + 1), "top");
      }
      for (let i = 0; i < 7; i++) {
        const g = (i === 0 || i === 6) ? "vE" : "vM";
        if (V.split) { add(s + i, Mn + i, g); add(Mn + i, TT + i, g); }
        else add(s + i, TT + i, g);
      }
      for (let i = 0; i < 6; i++) {
        const g = (i === 0 || i === 5) ? "dE" : "dM";
        if (i < 3) add(TT + i, s + (i + 1), g);     // Pratt: slopes toward midspan
        else add(TT + (i + 1), s + i, g);
      }
    }
    for (let i = 0; i < 7; i++) {
      add("TL" + i, "TR" + i, "strut");
      add("L" + i, "R" + i, "floor");
    }
    for (let i = 0; i < 6; i++) {
      add("TL" + i, "TR" + (i + 1), "tlat");
      add("L" + i, "R" + (i + 1), "blat");
    }
    if (V.endDiag) { add("L0", "TR0", "end"); add("R6", "TL6", "end"); }
    return { nodes: nodes, joints: joints, M: M };
  };

  const mkDesign = (T, ix, note) => ({
    note: note,
    nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: Object.assign({}, T.joints),
    members: T.M.map((m, k) => ({ a: m.a, b: m.b, spec: "S690 " + CH[ix[k]][0] }))
  });

  const feasible = (r) => {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.score === "number" && r.score <= 0) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > U_FEAS) return false;
    if (typeof r.fMin === "number" && r.fMin < F_MIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < A_MIN) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > S_LIM * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > S_LIM * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FAT_MAX) return false;
    if (r.robustness === false) return false;
    return typeof r.mass === "number";
  };

  const evalIx = (T, ix, note) => {
    if (outBudget()) return null;
    const d = mkDesign(T, ix, note);
    calls++;
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return null;
    const ok = feasible(r);
    if (ok && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d };
    return { r: r, ok: ok };
  };

  // Fully-stressed sizing per member, with group minima raised by guard failures.
  const sizeVariant = (V, maxIt) => {
    const T = topo(V);
    const nm = T.M.length;
    const ix = T.M.map(m => START[m.g]);
    const gmin = {};
    for (const g of GROUPS) gmin[g] = 0;
    const groupMin = (g) => {
      let mn = NC - 1;
      for (let k = 0; k < nm; k++) if (T.M[k].g === g && ix[k] < mn) mn = ix[k];
      return mn;
    };
    const bump = (gs) => {
      for (const g of gs) gmin[g] = Math.max(gmin[g], Math.min(NC - 1, groupMin(g) + 1));
    };
    let loc = null;
    for (let it = 0; it < maxIt; it++) {
      if (outBudget()) break;
      const ev = evalIx(T, ix, V.note);
      if (!ev) break;
      const r = ev.r;
      if (r.failure && /mechanism/i.test(String(r.failure))) break;
      if (ev.ok && (loc === null || r.mass < loc.mass)) loc = { mass: r.mass, ix: ix.slice() };
      const mp = {};
      for (const e of (r.members || [])) mp[e.id] = e;
      if (typeof r.alphaCr === "number" && r.alphaCr < 4.5) bump(["top", "strut", "tlat", "blat", "bot"]);
      if (typeof r.fMin === "number" && r.fMin < 4.6) bump(["top", "bot", "floor", "tlat", "blat"]);
      if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.5 * r.swayLimit)
        bump(["tlat", "blat", "strut", "top", "bot"]);
      if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.5 * r.sagLimit)
        bump(["top", "bot"]);
      const nx = ix.slice();
      let changed = false;
      for (let k = 0; k < nm; k++) {
        const m = T.M[k];
        const e = mp[m.a + "-" + m.b] || mp[m.b + "-" + m.a];
        let u = (e && typeof e.util === "number") ? e.util
              : ((typeof r.maxUtil === "number") ? r.maxUtil : 0.5);
        if (!(u > 0.02)) u = 0.02;
        const want0 = smallest(CH[ix[k]][1] * u / T_TGT);
        let want = Math.min(ix[k] + 3, Math.max(ix[k] - 3, want0));
        want = Math.max(want, gmin[m.g]);
        want = Math.min(NC - 1, Math.max(0, want));
        nx[k] = want;
        if (want !== ix[k]) changed = true;
      }
      if (!changed) break;
      for (let k = 0; k < nm; k++) ix[k] = nx[k];
    }
    return loc;
  };

  // Greedy trim: step each group down one section while the design stays feasible and lighter.
  const polish = (V, ix0, rounds) => {
    const T = topo(V);
    const nm = T.M.length;
    let cur = ix0.slice();
    const ev0 = evalIx(T, cur, V.note);
    if (!ev0 || !ev0.ok) return;
    let curMass = ev0.r.mass;
    for (let rd = 0; rd < rounds; rd++) {
      let improved = false;
      for (const g of GROUPS) {
        if (outBudget()) return;
        const cand = cur.slice();
        let any = false;
        for (let k = 0; k < nm; k++) {
          if (T.M[k].g === g && cand[k] > 0) { cand[k] -= 1; any = true; }
        }
        if (!any) continue;
        const ev = evalIx(T, cand, V.note);
        if (ev && ev.ok && ev.r.mass < curMass) {
          cur = cand; curMass = ev.r.mass; improved = true;
        }
      }
      if (!improved) break;
    }
  };

  const variants = [
    { split: true, endDiag: true, deck: "rigid",
      note: "All-rigid Pratt through-truss with rigid mid-height verticals and end-face diagonals; S690 CHS per member sized by iterated utilisation to 0.6 with alpha_cr, frequency, sway and sag guards, then greedy trim." },
    { split: true, endDiag: true, deck: "pin",
      note: "Pratt through-truss with rigid top and mid nodes, pinned deck nodes, end-face diagonals; S690 CHS per member sized by iterated utilisation with guards, then greedy trim." },
    { split: true, endDiag: false, deck: "rigid",
      note: "All-rigid Pratt through-truss without end-face diagonals; S690 CHS per member sized by iterated utilisation with guards, then greedy trim." }
  ];

  try {
    for (const V of variants) {
      if (outBudget()) break;
      const loc = sizeVariant(V, 14);
      if (loc && !outBudget()) polish(V, loc.ix, 2);
    }
  } catch (e) { /* fall through to best or fallback */ }

  if (best) {
    return { note: best.d.note, nodes: best.d.nodes, joints: best.d.joints, members: best.d.members };
  }
  // Fallback: all-rigid split truss with the largest permitted S690 CHS everywhere.
  const T3 = topo({ split: true, endDiag: true, deck: "rigid" });
  const fb = mkDesign(T3, T3.M.map(() => NC - 1),
    "Fallback: all-rigid Pratt truss with S690 CHS273x10 throughout.");
  return { note: fb.note, nodes: fb.nodes, joints: fb.joints, members: fb.members };
}
